use rs_decimal::validation::{ValidationRule, ValidationMessages};
let messages = ValidationMessages::with_messages(std::collections::BTreeMap::from([("decimal_required".into(), "Required: {0}".into())]))?;
let error = ValidationRule::parse("decimal_required", "")?.validate("amount{1}", &Decimal::default()).unwrap_err();
let value = serde_json::json!({"messages": messages.translate(&[error])});

